pub(crate) fn packagekit_schema() -> PluginSchema {
    let mut schema = PluginSchema::builder("packagekit")
        .version("1.0.0")
        .description("PackageKit package declarations")
        .field(
            "version",
            FieldSchema {
                field_type: FieldType::Integer,
                required: false,
                description: "Schema version".to_string(),
                default: Some(simd_json::json!(1)),
                example: None,
                constraints: vec![Constraint::Min { value: 1.0 }],
                read_only: false,
                read_only_when: None,
            },
        )
        .field(
            "packages",
            FieldSchema {
                field_type: FieldType::Any,
                required: true,
                description: "Package declaration map".to_string(),
                default: Some(simd_json::json!({})),
                example: None,
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        )
        .build();

    // org.freedesktop.PackageKit methods
    // Spec: https://www.freedesktop.org/software/PackageKit/gtk-doc/api-reference.html
    schema.methods.insert(
        "resolve".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<ResolvePackagesInput>(
            "Resolve",
            op_state_store::SideEffect::Read,
            true,
            "packagekit.read",
            "obs.software.packagekit.package.resolve@v1",
        ),
    );
    schema.methods.insert(
        "install_packages".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<InstallPackagesInput>(
            "InstallPackages",
            op_state_store::SideEffect::Write,
            false,
            "packagekit.admin",
            "mut.software.packagekit.package.install@v1",
        ),
    );
    schema.methods.insert(
        "remove_packages".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<RemovePackagesInput>(
            "RemovePackages",
            op_state_store::SideEffect::Write,
            false,
            "packagekit.admin",
            "mut.software.packagekit.package.remove@v1",
        ),
    );
    schema.methods.insert(
        "update_packages".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<UpdatePackagesInput>(
            "UpdatePackages",
            op_state_store::SideEffect::Write,
            false,
            "packagekit.admin",
            "mut.software.packagekit.package.update@v1",
        ),
    );
    schema.methods.insert(
        "get_updates".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<GetUpdatesInput>(
            "GetUpdates",
            op_state_store::SideEffect::Read,
            true,
            "packagekit.read",
            "obs.software.packagekit.updates.get@v1",
        ),
    );
    schema.methods.insert(
        "search_names".to_string(),
        super::plugin_schema_defs::method_decl_from_schemars::<SearchNamesInput>(
            "SearchNames",
            op_state_store::SideEffect::Read,
            true,
            "packagekit.read",
            "obs.software.packagekit.names.search@v1",
        ),
    );

    schema
}

// pcidecl_plugin.rs — declarative PCI device presence/config
// Query via /sys/bus/pci/devices/* and lspci fallback. Enforce supports "driver_override".
use anyhow::{Context, Result};
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::fs;
use std::path::Path;

use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PciDecl {
    pub version: u32,
    pub items: Vec<PciItem>,
}

#[derive(Debug, Copy, Clone, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Mode {
    Enforce,
    ObserveOnly,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PciItem {
    pub id: String, // stable id in your inventory
    pub mode: Mode,
    pub address: String, // 0000:00:1f.6
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expect_vendor: Option<String>, // "8086"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expect_device: Option<String>, // "15f3"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub driver_override: Option<String>, // desired override string or "" to clear
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PciLive {
    pub address: String,
    pub vendor: Option<String>,
    pub device: Option<String>,
    pub driver: Option<String>,
    pub driver_override: Option<String>,
    pub present: bool,
}

pub struct PciDeclPlugin;

impl Default for PciDeclPlugin {
    fn default() -> Self {
        Self
    }
}

impl PciDeclPlugin {
    pub fn new() -> Self {
        Self
    }

    fn sys_path(addr: &str) -> String {
        format!("/sys/bus/pci/devices/{}", addr)
    }

    fn read_to_string(path: &str) -> Option<String> {
        fs::read_to_string(path).ok().map(|s| s.trim().to_string())
    }

    fn live_for(addr: &str) -> PciLive {
        let root = Self::sys_path(addr);
        let present = Path::new(&root).exists();
        let vendor = Self::read_to_string(&format!("{}/vendor", root));
        let device = Self::read_to_string(&format!("{}/device", root));
        let drv_link = Path::new(&format!("{}/driver", root))
            .read_link()
            .ok()
            .and_then(|p| p.file_name().map(|s| s.to_string_lossy().to_string()));
        let drv_override = Self::read_to_string(&format!("{}/driver_override", root));
        PciLive {
            address: addr.to_string(),
            vendor,
            device,
            driver: drv_link,
            driver_override: drv_override,
            present,
        }
    }

    fn sysfs_present(addr: &str) -> bool {
        Path::new(&Self::sys_path(addr)).exists()
    }

    fn compliant(l: &PciLive, i: &PciItem) -> bool {
        if !l.present {
            return false;
        }
        if let Some(v) = &i.expect_vendor {
            if l.vendor.as_deref() != Some(&format!("0x{}", v).to_lowercase())
                && l.vendor.as_deref() != Some(v)
            {
                return false;
            }
        }
        if let Some(d) = &i.expect_device {
            if l.device.as_deref() != Some(&format!("0x{}", d).to_lowercase())
                && l.device.as_deref() != Some(d)
            {
                return false;
            }
        }
        if let Some(ovr) = &i.driver_override {
            if l.driver_override.as_deref() != Some(ovr.as_str()) {
                return false;
            }
        }
        true
    }

    fn set_driver_override(addr: &str, val: &str) -> Result<()> {
        let p = format!("{}/driver_override", Self::sys_path(addr));
        fs::write(&p, format!("{}\n", val)).context("write driver_override")?;
        Ok(())
    }
}

#[async_trait]
impl StatePlugin for PciDeclPlugin {
    fn name(&self) -> &str {
        "pcidecl"
    }
    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(
            PluginSchema::builder("pcidecl")
                .version("1.0.0")
                .description("PCI device declaration state")
                .field(
                    "version",
                    FieldSchema {
                        field_type: FieldType::Integer,
                        required: false,
                        description: "Schema version".to_string(),
                        default: Some(simd_json::json!(1)),
                        example: None,
                        constraints: vec![Constraint::Min { value: 1.0 }],
                        read_only: false,
                        read_only_when: None,
                    },
                )
                .field(
                    "items",
                    FieldSchema {
                        field_type: FieldType::Any,
                        required: true,
                        description: "PCI declarations".to_string(),
                        default: Some(simd_json::json!([])),
                        example: None,
                        constraints: Vec::new(),
                        read_only: false,
                        read_only_when: None,
                    },
                )
                .build(),
        )
    }

    async fn calculate_diff(&self, _current: &Value, desired: &Value) -> Result<StateDiff> {
        let want: PciDecl = simd_json::serde::from_owned_value(desired.clone())
            .context("desired must be PciDecl")?;
        let mut actions = Vec::new();
        for item in &want.items {
            let live = Self::live_for(&item.address);
            let present = live.present || Self::sysfs_present(&item.address);
            if let Mode::ObserveOnly = item.mode {
                actions.push(StateAction::NoOp {
                    resource: item.id.clone(),
                });
            } else {
                if !present {
                    actions.push(StateAction::NoOp {
                        resource: item.id.clone(),
                    });
                    continue;
                }
                if Self::compliant(&live, item) {
                    actions.push(StateAction::NoOp {
                        resource: item.id.clone(),
                    });
                } else {
                    actions.push(StateAction::Modify {
                        resource: item.id.clone(),
                        changes: simd_json::serde::to_owned_value(item)?,
                    });
                }
            }
        }
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute("pcidecl-current")),
                desired_hash: format!(
                    "{:x}",
                    md5::compute(simd_json::to_string(&desired).unwrap_or_default())
                ),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();
        for action in &diff.actions {
            match action {
                StateAction::Modify { resource, changes }
                | StateAction::Create {
                    resource,
                    config: changes,
                } => {
                    let item: PciItem = simd_json::serde::from_owned_value(changes.clone())
                        .context("invalid PciItem")?;
                    if let Some(val) = &item.driver_override {
                        match Self::set_driver_override(&item.address, val) {
                            Ok(_) => changes_applied
                                .push(format!("{}: driver_override -> {}", resource, val)),
                            Err(e) => errors.push(format!("{}: {}", resource, e)),
                        }
                    } else {
                        changes_applied.push(format!("{}: no changes required", resource));
                    }
                }
                StateAction::NoOp { resource } => {
                    changes_applied.push(format!("{}: no-op", resource));
                }
                StateAction::Delete { resource } => {
                    changes_applied.push(format!("{}: delete not supported", resource));
                }
            }
        }
        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let want: PciDecl =
            simd_json::serde::from_owned_value(desired.clone()).unwrap_or(PciDecl {
                version: 1,
                items: vec![],
            });
        for item in &want.items {
            let live = Self::live_for(&item.address);
            if !Self::compliant(&live, item) {
                return Ok(false);
            }
        }
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: format!("pcidecl-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::json!({}),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("pcidecl", |_ctx| std::sync::Arc::new(PciDeclPlugin::new()))
}

//! `persona` StatePlugin — projects the live agent-persona catalog from
//! `op-agents` through the `org.dbus.v1.plugins` surface (PluginService).
//!
//! This is the correct home for the capability the Lovable frontend mistakenly
//! called as a standalone `operation.agents.v1.PersonaService` gRPC package —
//! there is no such proto and there must not be one. New backend capabilities
//! register here as plugins (see OD-30 / [`crate::default_registry`]).
//!
//! The catalog is **live, not mocked**: the plugin's live state enumerates the
//! real built-in agent personas via `op_agents::builtin_agent_descriptors()`,
//! so the projection can never drift from the actual agent implementations. The
//! persona set is defined in code (op-agents), so it is read-only: mutating a
//! persona is rejected honestly rather than silently succeeding.

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_agents::builtin_agent_descriptors;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Persona {
    pub agent_type: String,
    pub name: String,
    pub description: String,
    pub operations: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PersonaState {
    pub status: String,
    pub persona_count: usize,
    pub personas: Vec<Persona>,
}

pub struct PersonaPlugin;

impl Default for PersonaPlugin {
    fn default() -> Self {
        Self::new()
    }
}

impl PersonaPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Enumerate the live persona catalog from the real agent implementations.
    /// Pure (no I/O) and deterministic, so it backs both the live state query
    /// and the schema exemplar.
    fn live() -> PersonaState {
        let personas: Vec<Persona> = builtin_agent_descriptors()
            .into_iter()
            .map(|d| Persona {
                agent_type: d.agent_type,
                name: d.name,
                description: d.description,
                operations: d.operations,
            })
            .collect();
        PersonaState {
            status: "active".to_string(),
            persona_count: personas.len(),
            personas,
        }
    }
}

#[async_trait]
impl StatePlugin for PersonaPlugin {
    fn name(&self) -> &str {
        "persona"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(persona_schema())
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        // The persona catalog is defined in code (op-agents); it is not runtime
        // mutable, so there is never anything to apply.
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![StateAction::NoOp {
                resource: "personas".to_string(),
            }],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        // Honest read-only behavior: NoOp is fine; any real mutation is rejected
        // with an explanation rather than pretending to succeed.
        let mut errors = Vec::new();
        for action in &diff.actions {
            match action {
                StateAction::NoOp { .. } => {}
                other => errors.push(format!(
                    "persona catalog is code-defined (op-agents) and read-only; \
                     cannot apply {:?}",
                    other
                )),
            }
        }
        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied: Vec::new(),
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let current = simd_json::serde::to_owned_value(Self::live())?;
        Ok(&current == desired)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::live())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        // Nothing to roll back: the catalog is code-defined.
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

pub(crate) fn persona_schema() -> PluginSchema {
    let state =
        simd_json::serde::to_owned_value(PersonaPlugin::live()).unwrap_or_else(|_| json!({}));
    schema_from_state(
        "persona",
        "agents",
        "1.0.0",
        "Agent persona catalog — built-in agent types, names, descriptions, operations",
        &state,
    )
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("persona", |_ctx| std::sync::Arc::new(PersonaPlugin::new()))
}

